export function trackLectureIds(trackKey: string): string[] {
  const t = tracks[trackKey]
  if (!t) return []
  const seen = new Set<string>()
  const ids: string[] = []
  for (const m of t.modules) {
    for (const id of m.lectureIds) {
      if (seen.has(id)) continue
      seen.add(id)
      ids.push(id)
    }
  }
  return ids
}

export function secondsFor(ids: string[]): number {
  let s = 0
  for (const id of ids) s += lectureById[id]?.sec ?? 0
  return s
}
